{
    "AWS_LargeInstances": "SELECT DOMAINNAME(domainId) AS 'DomainName', domainId AS 'Domain',\"Instance Size Type\" AS 'Instance Size Type', \"Instance ID\" AS 'Instance ID', \"Account ID\" AS 'Account ID', QIDNAME(qid) AS 'Event Name', LOGSOURCENAME(logSourceId) AS 'Log Source', eventCount AS 'Event Count', startTime AS 'Start Time', CATEGORYNAME(category) AS 'Low Level Category', sourceIP AS 'Source IP',sourcePort AS 'Source Port', destinationIP AS 'Destination IP', destinationPort AS 'Destination Port', \"Service Name\" AS 'Service Name', \"User Principal Name\" as 'User Principal Name' FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND \"Instance ID\" != 'null' AND \"Instance Size Type\" matches '.*large' AND \"deviceType\"='347' START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_PolicyChange": "SELECT DOMAINNAME(domainId) AS 'DomainName', domainId AS 'Domain', userName AS 'Username', categoryname(category) AS 'Low Level Category', QIDNAME(qid) AS 'Event Name', \"Policy Name\" AS 'Policy Name', \"Service Name\" AS 'Service Name', \"Region\" AS 'Region', startTime AS 'Start Time', sourceaddress AS 'Source Address', destinationaddress AS 'Destination Address', eventCount AS 'Event Count', \"User Principal Name\" as 'User Principal Name'  FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND \"Policy Name\" != 'AwsSSOInlinePolicy' AND \"deviceType\"='347' AND qid IN ('88750289', '88750685', '88750860', '88750868', '88750869', '88750904') AND \"userName\" != 'AWS-SSO' START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_GroupPolicyChanges": "SELECT DOMAINNAME(domainId) AS 'domainName', domainId AS 'Domain', \"Group Name\" AS 'Group Name', QIDNAME(qid) AS 'Event Name', userName AS 'Username', SUM(eventCount) AS 'Event Count', startTime AS 'Start Time', category AS 'Low Level Category', sourceaddress AS 'Source Address', destinationaddress AS 'Destination Address',sum(eventCount) AS 'Event Count' from events where DOMAINNAME(domainId) = '{customer_name}' AND ( ( ( \"deviceType\"='347' AND \"domainId\"='31' ) AND \"processorId\"='112' ) AND (qid='5772272') or (qid='69750008') or (qid='88750003') or (qid='88750058') or (qid='88750715') ) GROUP BY \"Group Name\" , QIDNAME(qid), userName , category, \"sourceaddress\", destinationaddress  START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_RolesCUD": "SELECT DOMAINNAME(domainId) AS 'DomainName', DomainId AS 'Domain', sourceIP AS 'Source IP', QIDNAME(qid) AS 'Event Name', userName AS 'Username', \"Role Name\" AS 'Role Name', \"Account ID\" AS 'Account ID', LOGSOURCENAME(logSourceId) AS 'Log Source', eventCount AS 'Event Count', CATEGORYNAME(category) AS 'Low Level Category', startTime AS 'Start Time', sourcePort AS 'Source Port', destinationIP AS 'Destination IP', destinationPort AS 'Destination Port', \"Service Name\" AS 'Service Name', \"User Principal Name\" as 'User Principal Name' FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND deviceType ='347' AND qid IN ('88750189', '88750294', '88750295', '88750295') START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_UserCreated": "SELECT DOMAINNAME(domainId) AS 'DomainName', domainId AS 'Domain', \"Account Name\" AS 'Account Name', \"Log Type\" AS 'Log Type', sourceIP AS 'Source IP', QIDNAME(qid) AS 'Event Name',  userName AS 'Username', \"Account ID\" AS 'Account ID', eventCount AS 'Event Count', startTime AS 'Start Time', CATEGORYNAME(category) AS 'Low Level Category', sourcePort AS 'Source Port', destinationIP AS 'Destination IP', destinationPort AS 'Destination Port', \"Service Name\" AS 'Service Name', \"Target Username\" AS 'Target Username', \"User Principal Name\" as 'User Principal Name' FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND \"Log Type\" IN ('connect.amazonaws.com', 'quicksight.amazonaws.com', 'sso-directory.amazonaws.com', 'transfer.amazonaws.com') AND \"deviceType\"='347' AND qid='88750203' START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_AuditEvents": "SELECT DOMAINNAME(domainId) AS 'DomainName', DomainId AS 'Domain', QIDNAME(qid) AS 'Event Name', userName AS 'Username', \"Service Name\" AS 'Service Name', \"Region\" AS 'Region', sourceaddress AS 'Source Address', destinationaddress AS 'Destination Address', startTime AS 'Start Time', CATEGORYNAME(category) AS 'Low Level Category', eventCount AS 'Event Count', \"User Principal Name\" as 'User Principal Name' FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND qid IN('88750001','88750003','88750037','88750077','88750100','88750119','88750126','88750159','88750167','88750176','88750178','88750200','88750225','88750266','88750271','88750273','88750274','88750281','88750289','88750300','88750309','88750323','88750649','88750650','88750698','88750707','88750710','88750751','88750823','88750860','88750861','88750868') START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_BucketsCreation": "SELECT DOMAINNAME(domainId) AS 'domainName', domainId AS 'Domain', \"Policy Name\" , \"Account ID\" AS 'Account ID', \"userName\" AS 'Username', \"Service Name\" AS 'Service Name', \"Storage Name\" AS 'Storage Name', \"sourceIP\" AS 'Source IP', QIDNAME(qid) AS 'Event Name', LOGSOURCENAME(logSourceId) AS 'Log Source', eventCount AS 'Event Count', startTime AS 'Start Time', CATEGORYNAME(category) AS 'Low Level Category',sourcePort AS 'Source Port', destinationIP AS 'Destination IP', destinationPort AS 'Destination Port', magnitude AS 'Magnitude' FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND \"Event Name\" = 'Create Bucket' AND deviceType='347' START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_BucketsDeletion": "SELECT DOMAINNAME(domainId) AS 'DomainName', domainId AS 'Domain', \"Account ID\" AS 'Account ID', \"userName\" AS 'Username', QIDNAME(qid) AS 'Event Name', \"Storage Name\" AS 'Storage Name', \"sourceIP\" AS 'Source IP', LOGSOURCENAME(logSourceId) AS 'Log Source', eventCount AS 'Event Count', startTime AS 'Start Time', CATEGORYNAME(category) AS 'Low Level Category',sourcePort AS 'Source Port', destinationIP AS 'Destination IP', destinationPort AS 'Destination Port', \"Service Name\" AS 'Service Name', \"User Principal Name\" as 'User Principal Name' FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND \"Event Name\" ='Delete Bucket' AND deviceType='347' START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_VPCAuditEvent": "SELECT DOMAINNAME(domainId) AS 'DomainName', domainId AS 'Domain', \"Account Name\" AS 'Account Name', userName AS 'Username', CATEGORYNAME(category) AS 'Low Level Category', QIDNAME(qid) AS 'Event Name', \"Service Name\" AS 'Service Name', \"Region\" AS 'Region', startTime AS 'Start Time', sourceaddress AS 'Source Address', destinationaddress AS 'Destination Address', eventCount AS 'Event Count', \"User Principal Name\" as 'User Principal Name' FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND deviceType = '347' AND qid IN ('88750027', '88750479', '88750027', '88750479', '88750898', '88750899', '88750900', '88750901', '88750901') AND referencesetcontains('AWS - VPC Events', qid) START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",

    "AWS_TopAssumeRoleName": "SELECT DOMAINNAME(domainId) as 'DomainName',domainId AS 'Domain', sourceIP  AS  'Source IP', \"Role Name\" AS 'Role Name', EventName AS 'Event Name', \"Service Name\" AS 'Service Name', eventCount AS 'Event Count', startTime AS 'Start Time' FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND ( \"Role Name\" <> null AND \"deviceType\"='347' ) START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_TopRegion": "SELECT DOMAINNAME(domainId) as 'DomainName', domainId AS 'Domain', sourceIP AS 'Source IP', \"Region\" AS 'Region', \"Account ID\" AS 'Account ID', startTime AS 'Start Time', eventCount AS 'Event Count', EventName AS 'Event Name' FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND ( \"Role Name\" <> null AND \"deviceType\"='347' ) START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_LeastRegion": "SELECT DOMAINNAME(domainId) as 'DomainName',domainId AS 'Domain', \"Region\" AS 'Region', sourceIP AS 'Source IP', EventName AS 'Event Name', userName AS 'Username', \"Service Name\" AS 'Service Name', \"Action Result\" AS 'Action Result',\"Role Name\" AS 'Role Name', deviceType as 'Device Type', \"Account ID\" AS 'Account ID', LOGSOURCENAME(logSourceId) AS 'Log Source', eventCount AS 'Event Count', startTime AS 'Start Time', CATEGORYNAME(category) AS 'Low Level Category', sourcePort AS 'Source Port', destinationIP AS 'Destination IP', destinationPort AS 'Destination Port' from events where DOMAINNAME(domainId) = '{customer_name}' AND ( \"Role Name\" <> null AND \"deviceType\"='347' ) PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))", 
    "AWS_TopErrorMessage": "SELECT DOMAINNAME(domainId) as 'DomainName',domainId AS 'Domain', \"User Type\" as 'User Type',QIDNAME(qid) AS 'Event Name', \"Error Code\" AS 'Error Code', \"Error Info\" as 'Error Info', sourceIP AS 'Source IP', startTime AS 'Start Time', eventCount AS 'Event Count'from events where DOMAINNAME(domainId) = '{customer_name}' AND ( \"Error Info\" <> null AND \"deviceType\"='347' ) START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",    
    "AWS_TopIAMUsers": "SELECT DOMAINNAME(domainId) as 'DomainName',domainId AS 'Domain', \"User Type\" as 'User Type', \"userName\" AS 'Username', startTime AS 'Start Time', eventCount AS 'Event Count', sourceIP AS 'Source IP', QIDNAME(qid)  AS  'Event Name' from events where DOMAINNAME(domainId) = '{customer_name}' AND ((\"User Agent\" != 'sqs.amazonaws.com') AND (\"User Type\"  ILIKE ENUMERATION ('%IAMUser%','%federateduser%','%SAMLuser%')) AND \"deviceType\"='347' AND \"userName\" <> null) START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    "AWS_RootLoginV1": "SELECT DOMAINNAME(domainId) as 'DomainName',domainId AS 'Domain',\"EventName\" AS 'Event Name', \"sourceIP\" AS 'Source IP', \"userName\" AS 'Username', \"Account ID\" AS 'Account ID',\"User Type\" as 'User Type',\"deviceType\" as 'Device Type', \"Action Result\" AS 'Action Result', \"Region\" AS 'Region', \"Service Name\" AS 'Service Name', LOGSOURCENAME(logSourceId) AS 'Log Source', eventCount AS 'Event Count', startTime AS 'Start Time', CATEGORYNAME(category) AS 'Low Level Category', sourcePort AS 'Source Port', destinationIP AS 'Destination IP', destinationPort AS 'Destination Port', magnitude AS 'Magnitude' from events where DOMAINNAME(domainId) = '{customer_name}' AND ( \"User Type\" ilike '%root%' AND \"deviceType\"='347' ) PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))",
    // "AWS_TopEventName": "SELECT DOMAINNAME(domainId) as 'DomainName',domainId AS 'Domain', \"User Type\" as 'User Type', QIDNAME(qid) AS 'Event Name',startTime AS 'Start Time', sourceIP  AS  'Source IP', CATEGORYNAME(category) AS 'Low Level Category', deviceType as 'Device Type', LOGSOURCENAME(logSourceId) AS 'Log Source',eventCount AS 'Event Count', LOGSOURCETYPENAME(devicetype) AS 'Log Source Type'  FROM events WHERE DOMAINNAME(domainId) = '{customer_name}' AND qid != '94000001' START '{start_time}' STOP '{stop_time}' PARAMETERS REMOTESERVERS=ARIELSERVERS4EPNAME(PROCESSORNAME({event_processor}))"
    
}


